export const PHONE_FONTS={system:{name:'System sans',css:'system-ui, sans-serif'},humanist:{name:'Humanist',css:'Trebuchet MS, sans-serif'},serif:{name:'Book serif',css:'Georgia, serif'},mono:{name:'Clear mono',css:'Consolas, monospace'}};
export const MUSIC_TRACKS=[{id:'courtyard',name:'Courtyard Morning',file:'assets/music/courtyard.wav',detail:'Original mellow keys · 24-second loop'},{id:'lagoon',name:'Lagoon Walk',file:'assets/music/lagoon.wav',detail:'Original plucked keys and soft percussion · 24-second loop'}];
export function migratePhone(s,data){s.phoneAppearance={...s.phoneAppearance,font:data?.phoneAppearance?.font||'system',theme:data?.phoneAppearance?.theme||'night'};s.music={track:'courtyard',volume:.35,...data?.music};}
export function validPhone(s){return (!s.music||MUSIC_TRACKS.some(t=>t.id===s.music.track)&&Number.isFinite(s.music.volume)&&s.music.volume>=0&&s.music.volume<=1)&&(!s.phoneAppearance?.font||Object.hasOwn(PHONE_FONTS,s.phoneAppearance.font))&&(!s.phoneAppearance?.theme||['night','forest','plum'].includes(s.phoneAppearance.theme));}
export function applyPhoneAppearance(sheet,state){sheet.style.fontFamily=PHONE_FONTS[state.phoneAppearance.font]?.css||PHONE_FONTS.system.css;sheet.dataset.phoneTheme=state.phoneAppearance.theme||'night';}
export function createFontsApp({root,state,save,sheet}){
 let preview=state.phoneAppearance.font;const draw=()=>{root.innerHTML='<p>Readable fonts for your in-game phone.</p>'+Object.entries(PHONE_FONTS).map(([id,f])=>'<button id="font-'+id+'">'+f.name+'</button>').join('')+'<div id="font-preview" class="card"><h3>A day in Lagos</h3><p>Shopping · Messages · Gallery<br>Balance ₦15,000 · 08:30</p></div><button id="font-apply">Apply font</button><p id="font-result" role="status"></p>';root.querySelector('#font-preview').style.fontFamily=PHONE_FONTS[preview].css;for(const id of Object.keys(PHONE_FONTS))root.querySelector('#font-'+id).onclick=()=>{preview=id;draw();};root.querySelector('#font-apply').onclick=()=>{state.phoneAppearance.font=preview;save();applyPhoneAppearance(sheet,state);root.querySelector('#font-result').textContent='Font saved.';};};draw();return {tick(){},dispose(){}};
}
export function createMusicPlayer({state,save}){
 let audio=null,error='',busy=false;const listeners=new Set(),notify=()=>listeners.forEach(fn=>fn());
 function get(){if(!audio){audio=new Audio();audio.loop=true;audio.preload='none';audio.onended=notify;audio.onerror=()=>{error='This track could not play. Try again after checking browser audio.';notify();};}return audio;}
 function pause(){audio?.pause();notify();}
 async function play(){if(busy)return;busy=true;try{const a=get(),track=MUSIC_TRACKS.find(t=>t.id===state.music.track);if(a.dataset.track!==track.id){a.src=track.file;a.dataset.track=track.id;}a.volume=state.music.volume;await a.play();error='';}catch{error='Playback was blocked. Tap Play again to enable audio.';}finally{busy=false;notify();}}
 function screen(root){const draw=()=>{root.innerHTML='<p>Bundled original instrumentals. Playback starts only when you press Play.</p>'+MUSIC_TRACKS.map(t=>'<button id="track-'+t.id+'">'+t.name+'<small>'+t.detail+'</small></button>').join('')+'<p id="music-status" role="status"></p><button id="music-play">Play</button><button id="music-pause">Pause</button><label>Music volume<input id="music-volume" type="range" min="0" max="1" step=".05"></label>';root.querySelector('#music-status').textContent=error||MUSIC_TRACKS.find(t=>t.id===state.music.track).name+' · '+(audio&&!audio.paused?'Playing':'Paused');for(const t of MUSIC_TRACKS)root.querySelector('#track-'+t.id).onclick=()=>{pause();state.music.track=t.id;save();draw();};root.querySelector('#music-play').onclick=play;root.querySelector('#music-pause').onclick=pause;const v=root.querySelector('#music-volume');v.value=state.music.volume;v.oninput=()=>{state.music.volume=Number(v.value);if(audio)audio.volume=state.music.volume;save();};};listeners.add(draw);draw();return {tick(){},dispose(){listeners.delete(draw);}};}
 addEventListener('pagehide',pause);addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});return {screen,pause};
}
